def minCostClimbingStairs(cost):
    n = len(cost)
    if n == 0:
        return 0
    if n == 1:
        return cost[0]

    prev2, prev1 = cost[0], cost[1]
    for i in range(2, n):
        current = cost[i] + min(prev2, prev1)
        prev2, prev1 = prev1, current

    return min(prev2, prev1)

